// Package lockfile implements reading and writing llm-proxy.lock.hcl — the
// lock file that records the concrete resolved version for every declared
// plugin.
//
// The lock file is written adjacent to the operator's config file (or inside
// the config directory when a directory is used as the config root). It must
// be committed to source control so that every team member and CI run uses
// exactly the same plugin binaries.
//
// File format (HCL2):
//
//	# llm-proxy.lock.hcl — DO NOT EDIT BY HAND
//	# Generated by `llm-proxy plugin install`.
//
//	plugin "myplugin" {
//	  source   = "github.com/example/llm-proxy-provider-myplugin"
//	  version  = "~> 1.0"          # constraint from config
//	  resolved = "1.2.3"           # concrete version selected
//	  platform = "darwin_arm64"    # os_arch at resolution time
//	}
//
// The lock file is keyed by (name, platform) so that a team mixing macOS and
// Linux workstations each get their own resolution recorded without conflict.
// `llm-proxy plugin install` always re-resolves for the current platform and
// updates the matching entry.
package lockfile

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strings"

	"github.com/hashicorp/hcl/v2"
	"github.com/hashicorp/hcl/v2/gohcl"
	"github.com/hashicorp/hcl/v2/hclparse"
	"github.com/hashicorp/hcl/v2/hclwrite"
	"github.com/zclconf/go-cty/cty"
)

const (
	// FileName is the conventional name for the lock file.
	FileName = "llm-proxy.lock.hcl"

	// header is prepended to every written lock file.
	header = "# llm-proxy.lock.hcl — DO NOT EDIT BY HAND\n" +
		"# Generated by `llm-proxy plugin install`.\n\n"
)

// ErrNotFound is returned when the lock file does not exist.
var ErrNotFound = errors.New("lock file not found")

// Entry records the resolved state for a single plugin on a specific platform.
type Entry struct {
	// Name is the plugin label (matches the plugin HCL block label).
	Name string
	// Source is the source URL from the plugin block.
	Source string
	// Constraint is the version constraint string from the plugin block
	// (e.g. "~> 1.0").
	Constraint string
	// Resolved is the concrete semver string selected at install time
	// (e.g. "1.2.3", no leading "v").
	Resolved string
	// Platform is the "os_arch" tuple for which this entry was resolved.
	Platform string
}

// Lockfile holds all recorded plugin entries.
type Lockfile struct {
	entries []Entry
}

// hclPluginBlock is the intermediate HCL decode target.
type hclPluginBlock struct {
	Name       string `hcl:",label"`
	Source     string `hcl:"source"`
	Constraint string `hcl:"version"`
	Resolved   string `hcl:"resolved"`
	Platform   string `hcl:"platform"`
}

// hclLockFile is the top-level HCL decode target.
type hclLockFile struct {
	Plugins []hclPluginBlock `hcl:"plugin,block"`
	Remain  hcl.Body         `hcl:",remain"`
}

// Lookup returns the entry for the named plugin on the current platform,
// reporting whether it was found.
func (lf *Lockfile) Lookup(name string) (Entry, bool) {
	platform := currentPlatform()
	for _, e := range lf.entries {
		if e.Name == name && e.Platform == platform {
			return e, true
		}
	}
	return Entry{}, false
}

// Set records or replaces the entry for the given plugin on the current
// platform.
func (lf *Lockfile) Set(e Entry) {
	platform := currentPlatform()
	e.Platform = platform
	for i, existing := range lf.entries {
		if existing.Name == e.Name && existing.Platform == platform {
			lf.entries[i] = e
			return
		}
	}
	lf.entries = append(lf.entries, e)
}

// Entries returns a copy of all entries, sorted by (name, platform) for
// deterministic output.
func (lf *Lockfile) Entries() []Entry {
	out := make([]Entry, len(lf.entries))
	copy(out, lf.entries)
	sort.Slice(out, func(i, j int) bool {
		if out[i].Name != out[j].Name {
			return out[i].Name < out[j].Name
		}
		return out[i].Platform < out[j].Platform
	})
	return out
}

// Read reads and parses the lock file at path.
// It returns ErrNotFound (wrapped) when the file does not exist.
func Read(path string) (*Lockfile, error) {
	data, err := os.ReadFile(path) //nolint:gosec // operator-controlled path
	if err != nil {
		if os.IsNotExist(err) {
			return nil, fmt.Errorf("%w: %s", ErrNotFound, path)
		}
		return nil, fmt.Errorf("read lock file %q: %w", path, err)
	}

	parser := hclparse.NewParser()
	f, diags := parser.ParseHCL(data, path)
	if diags.HasErrors() {
		return nil, fmt.Errorf("parse lock file %q: %s", path, diags.Error())
	}
	if f == nil {
		return nil, fmt.Errorf("parse lock file %q: nil result", path)
	}

	var raw hclLockFile
	if diags := gohcl.DecodeBody(f.Body, nil, &raw); diags.HasErrors() {
		return nil, fmt.Errorf("decode lock file %q: %s", path, diags.Error())
	}

	lf := &Lockfile{}
	for _, pb := range raw.Plugins {
		//nolint:staticcheck // hclPluginBlock field names differ from Entry; struct literal is correct
		lf.entries = append(lf.entries, Entry{
			Name:       pb.Name,
			Source:     pb.Source,
			Constraint: pb.Constraint,
			Resolved:   pb.Resolved,
			Platform:   pb.Platform,
		})
	}
	return lf, nil
}

// Write serialises the lock file to path, creating parent directories with
// mode 0700 if needed. The file is written atomically via a sibling temp file.
func Write(path string, lf *Lockfile) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return fmt.Errorf("create lock file dir: %w", err)
	}

	f := hclwrite.NewEmptyFile()
	root := f.Body()

	entries := lf.Entries() // sorted for determinism
	for i, e := range entries {
		if i > 0 {
			root.AppendNewline()
		}
		block := root.AppendNewBlock("plugin", []string{e.Name})
		body := block.Body()
		body.SetAttributeValue("source", cty.StringVal(e.Source))
		body.SetAttributeValue("version", cty.StringVal(e.Constraint))
		body.SetAttributeValue("resolved", cty.StringVal(e.Resolved))
		body.SetAttributeValue("platform", cty.StringVal(e.Platform))
	}

	content := []byte(header)
	content = append(content, f.Bytes()...)

	// Atomic write via temp file.
	dir := filepath.Dir(path)
	tmp, err := os.CreateTemp(dir, ".lock-tmp-*")
	if err != nil {
		return fmt.Errorf("create temp file: %w", err)
	}
	tmpName := tmp.Name()
	ok := false
	defer func() {
		if !ok {
			_ = os.Remove(tmpName)
		}
	}()
	if _, err := tmp.Write(content); err != nil {
		_ = tmp.Close()
		return fmt.Errorf("write lock file: %w", err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("close lock file: %w", err)
	}
	if err := os.Rename(tmpName, path); err != nil {
		return fmt.Errorf("rename lock file: %w", err)
	}
	ok = true
	return nil
}

// PathFor derives the lock file path from the operator's config path.
//
// If configPath points at a file, the lock file lives adjacent to it.
// If configPath points at a directory, the lock file lives inside it.
func PathFor(configPath string) (string, error) {
	info, err := os.Stat(configPath)
	if err != nil {
		// Config path may not exist yet (e.g. default path before first run).
		// Fall back to treating it as a file and placing the lockfile next to it.
		//nolint:nilerr // intentional: non-existence is handled gracefully
		return filepath.Join(filepath.Dir(configPath), FileName), nil
	}
	if info.IsDir() {
		return filepath.Join(configPath, FileName), nil
	}
	return filepath.Join(filepath.Dir(configPath), FileName), nil
}

// currentPlatform returns the "os_arch" identifier for the running binary.
func currentPlatform() string {
	return runtime.GOOS + "_" + runtime.GOARCH
}

// NormalisePlatform ensures the platform string is in the canonical
// "os_arch" form (lowercase, underscore separator). It is exported for use
// by tests that need to build expected values portably.
func NormalisePlatform(goos, goarch string) string {
	return strings.ToLower(goos) + "_" + strings.ToLower(goarch)
}
